<?php use App\Core\Url; use App\Core\View; ?>
    <header><a href="<?= Url::to('/dashboard') ?>" class="text-sm text-green-300 hover:text-green-200">← Dashboard</a><h1 class="mt-2 text-3xl font-semibold">Academic setup</h1><p class="mt-1 text-sm text-white">Manage years, classes, shifts, and sections.</p></header>
    <section class="mt-7 grid gap-5 xl:grid-cols-2">
      <article class="rounded-2xl border border-green-900/60 bg-[#0b3425]/80 p-5"><div class="flex items-start justify-between"><div><h2 class="font-semibold">Academic years</h2><p class="mt-1 text-sm text-slate-500">Choose the year used for new admissions.</p></div><span class="rounded-full bg-slate-800 px-2.5 py-1 text-xs text-white"><?= count($years) ?> total</span></div><div class="mt-4 space-y-2"><?php foreach ($years as $year): ?><div class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-green-900/60 p-3"><div><p class="font-medium"><?= View::escape($year['name']) ?><?php if ($year['is_current']): ?> <span class="ml-2 rounded-full bg-green-400/10 px-2 py-1 text-[10px] font-semibold uppercase text-green-200">Current</span><?php endif; ?></p><p class="mt-1 text-xs text-slate-500"><?= View::escape($year['start_date']) ?> — <?= View::escape($year['end_date']) ?></p></div><?php if (!$year['is_current']): ?><form method="post" action="<?= Url::to('/academics/years/current') ?>"><?= \App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int) $year['id'] ?>"><button class="rounded-lg border border-slate-700 px-3 py-2 text-xs text-slate-300 hover:border-green-400">Make current</button></form><?php endif; ?></div><?php endforeach; if ($years === []): ?><p class="rounded-xl border border-dashed border-slate-700 p-5 text-center text-sm text-slate-500">No academic year configured.</p><?php endif; ?></div><form method="post" action="<?= Url::to('/academics/years') ?>" class="mt-5 grid gap-3 border-t border-green-900/60 pt-5 sm:grid-cols-2"><?= \App\Core\Csrf::field() ?><label class="text-sm sm:col-span-2"><span class="mb-1.5 block text-slate-300">Year name</span><input required maxlength="20" name="name" placeholder="2027" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"></label><label class="text-sm"><span class="mb-1.5 block text-slate-300">Starts</span><input required type="date" name="start_date" value="<?= date('Y') ?>-01-01" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"></label><label class="text-sm"><span class="mb-1.5 block text-slate-300">Ends</span><input required type="date" name="end_date" value="<?= date('Y') ?>-12-31" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"></label><button class="rounded-lg bg-green-400 px-4 py-2.5 text-sm font-semibold text-slate-950 hover:bg-green-300 sm:col-span-2">Add academic year</button></form></article>
      <article class="rounded-2xl border border-green-900/60 bg-[#0b3425]/80 p-5"><div class="flex items-start justify-between"><div><h2 class="font-semibold">Classes & sections</h2><p class="mt-1 text-sm text-slate-500">Class levels support Bangladesh Classes 1–10.</p></div><span class="rounded-full bg-slate-800 px-2.5 py-1 text-xs text-white"><?= count($classes) ?> classes</span></div><div class="mt-4 space-y-2"><?php foreach ($classes as $class): ?><div class="rounded-xl border border-green-900/60 p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div><p class="font-medium"><?= View::escape($class['name']) ?> <span class="text-xs text-slate-500">Level <?= (int) $class['numeric_level'] ?> · <?= View::escape($class['shift']) ?> shift</span></p><p class="mt-1 text-xs text-slate-500">Sections: <?= $class['section_names'] ? View::escape($class['section_names']) : 'None added' ?></p></div><span class="text-xs text-slate-500"><?= (int) $class['section_count'] ?> section<?= (int) $class['section_count'] === 1 ? '' : 's' ?></span></div><form method="post" action="<?= Url::to('/academics/sections') ?>" class="mt-3 grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><?= \App\Core\Csrf::field() ?><input type="hidden" name="class_id" value="<?= (int) $class['id'] ?>"><label class="sr-only" for="section-<?= (int) $class['id'] ?>">Section name</label><input id="section-<?= (int) $class['id'] ?>" required maxlength="20" name="name" placeholder="New section, e.g. B" class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm"><label class="sr-only" for="room-<?= (int) $class['id'] ?>">Room number</label><input id="room-<?= (int) $class['id'] ?>" maxlength="30" name="room_no" placeholder="Room (optional)" class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm"><button class="rounded-lg border border-slate-700 px-3 py-2 text-xs hover:border-green-400">Add section</button></form></div><?php endforeach; if ($classes === []): ?><p class="rounded-xl border border-dashed border-slate-700 p-5 text-center text-sm text-slate-500">No classes configured.</p><?php endif; ?></div><form method="post" action="<?= Url::to('/academics/classes') ?>" class="mt-5 grid gap-3 border-t border-green-900/60 pt-5 sm:grid-cols-2"><?= \App\Core\Csrf::field() ?><label class="text-sm sm:col-span-2"><span class="mb-1.5 block text-slate-300">Class name</span><input required maxlength="50" name="name" placeholder="Class 6" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"></label><label class="text-sm"><span class="mb-1.5 block text-slate-300">Level</span><select required name="numeric_level" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"><?php for ($level = 1; $level <= 10; $level++): ?><option value="<?= $level ?>">Class level <?= $level ?></option><?php endfor; ?></select></label><label class="text-sm"><span class="mb-1.5 block text-slate-300">Shift</span><select name="shift" class="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5"><option>Morning</option><option>Day</option><option>Both</option></select></label><button class="rounded-lg bg-green-400 px-4 py-2.5 text-sm font-semibold text-slate-950 hover:bg-green-300 sm:col-span-2">Add class</button></form></article>
    </section>

